CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, session_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE books (id INTEGER PRIMARY KEY AUTOINCREMENT, code VARCHAR(40) NOT NULL UNIQUE, title TEXT NOT NULL, subtitle TEXT, author TEXT, isbn VARCHAR(13) UNIQUE, publisher TEXT, pvp INTEGER, active INTEGER NOT NULL DEFAULT 1, edition TEXT, year INTEGER, format TEXT, width TEXT, height TEXT, pages INTEGER, synopsis TEXT, notes TEXT, cover TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE login_attempts (key_hash VARCHAR(64) PRIMARY KEY, attempts INTEGER NOT NULL, started INTEGER NOT NULL);
